  const grad = await graduatoriaFinale(disciplinaId).catch(() => null);
  const puntiCoppa = grad ? JSON.stringify(grad.map((r) => ({ casata_id: r.id, nome: r.nome, posizione: r.posizione, punti: r.punti }))) : null;
