  const selFase = (fase) => db.prepare("SELECT id,giornata,casa_a,casa_b,gol_a,gol_b,stato,fase,quando,luogo FROM partite WHERE disciplina_id=? AND fase=? ORDER BY giornata,id").all(disciplinaId, fase);
