var app = express();
app.disable("x-powered-by");
app.use(express.json({ limit: "8mb" }));
app.use((req, res, next) => {
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "SAMEORIGIN");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  res.setHeader(
    "Content-Security-Policy",
    "default-src 'self'; img-src 'self' data: https://maps.gstatic.com https://*.googleapis.com; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; frame-src https://www.google.com https://maps.google.com https://*.google.com; frame-ancestors 'self'"
  );
  next();
});
app.use((req, res, next) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
  if (req.method === "OPTIONS") return res.sendStatus(204);
  next();
});
mountPwa(app);
app.get("/api/health", (req, res) => res.json({ ok: true, version: VERSION, build: BUILD, env: process.env.KOINE_ENV || "online", ts: (/* @__PURE__ */ new Date()).toISOString() }));
app.use("/api/auth", authUserRouter);
app.use("/api", publicRouter);
app.use("/api/admin", adminRouter);
var html = (res, body) => {
  res.setHeader("Cache-Control", "no-cache");
  res.type("html").send(body);
};
app.get(["/", "/index.html"], (req, res) => html(res, FRONTEND));
app.get(["/admin", "/admin/", "/admin/index.html"], (req, res) => html(res, ADMIN));
app.get(["/chiosco", "/chiosco/", "/chiosco/index.html"], (req, res) => html(res, CHIOSCO));
